import subprocess

def run(args, stdin_data, timeout=3):
    try:
        p = subprocess.run(["./executable"]+args, input=stdin_data, capture_output=True, text=True, timeout=timeout)
        return (p.returncode, p.stdout, p.stderr)
    except subprocess.TimeoutExpired as e:
        out = e.stdout.decode() if isinstance(e.stdout, bytes) else (e.stdout or "")
        err = e.stderr.decode() if isinstance(e.stderr, bytes) else (e.stderr or "")
        return ("TIMEOUT", out[:1000], err[:1000])

def t(desc, args, stdin_data):
    rc,out,err = run(args, stdin_data)
    print(f"=== {desc} ===")
    print(f"args={args} stdin={repr(stdin_data)[:400]}")
    print(f"rc={rc} out={repr(out[:5000])} err={repr(err[:5000])}")
    print()

