import pty, os, subprocess, select, time

def run_with_tty(cmd, timeout=3):
    # Use pty to run with tty stdin/stdout
    master, slave = pty.openpty()
    p = subprocess.Popen(cmd, stdin=slave, stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    output = b""
    start = time.time()
    while time.time() - start < timeout:
        r,_,_ = select.select([master], [], [], 0.5)
        if r:
            try:
                data = os.read(master, 1024)
                if not data:
                    break
                output += data
            except OSError:
                break
        if p.poll() is not None:
            # process exited, read remaining
            time.sleep(0.2)
            try:
                while True:
                    r,_,_ = select.select([master], [], [], 0.2)
                    if not r:
                        break
                    data = os.read(master, 1024)
                    if not data:
                        break
                    output += data
            except OSError:
                pass
            break
    try:
        p.terminate()
    except: pass
    try:
        os.close(master)
    except: pass
    # wait
    try:
        rc = p.wait(timeout=1)
    except:
        rc = "timeout"
    return rc, output

for cmd in [["./executable", ".a"], ["./executable", "/nonexistent.json"], ["./executable", "/tmp"], ["./executable", "/tmp/f1.json", ".a"]]:
    rc, out = run_with_tty(cmd)
    print(f"cmd={cmd} rc={rc} out={repr(out[:2000])}")
    print("---")

