package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

var flagCompletions = []string{"--help", "--raw", "--slurp", "--themes", "--version", "--yaml", "--toml", "--strict", "--no-inline"}

var globalCompletions = []string{
	"apply", "len", "uniq", "sort", "isFalsely", "filter", "map", "walk", "sortBy", "sortKeys", "groupBy", "chunk", "console.log", "zip", "flatten", "reverse", "keys", "values", "list", "del", "exit", "save", "toBase64", "fromBase64",
	"Array.isArray", "Array.from", "JSON.stringify", "JSON.parse", "Object.keys", "Object.values", "Object.entries", "Object.fromEntries", "YAML.stringify", "YAML.parse",
}

func doZshCompletion(line string) {
	results := computeCompletion(line, true)
	for _, r := range results {
		fmt.Fprintf(os.Stdout, "%s\t%s\t%s\n", r.display, r.value, r.typ)
	}
	// if empty, output nothing (not even newline)
}

func doFishCompletion(line string) {
	results := computeCompletion(line, false)
	for _, r := range results {
		fmt.Fprintf(os.Stdout, "%s\n", r.value)
	}
}

func doBashCompletion(args []string) {
	// args are os.Args[1:], need len>=2, cur = args[1]
	if len(args) < 2 {
		return
	}
	cur := args[1]
	compLine := os.Getenv("COMP_LINE")
	results := computeBashCompletion(compLine, cur)
	for _, r := range results {
		fmt.Fprintf(os.Stdout, "%s\n", r.value)
	}
}

type compResult struct {
