func completeFlags(prefix string, isZsh bool) []compResult {
	var res []compResult
	for _, f := range flagCompletions {
		if strings.HasPrefix(f, prefix) {
			if isZsh {
				res = append(res, compResult{display: f, value: f, typ: "flag"})
			} else {
				res = append(res, compResult{value: f})
			}
		}
	}
	return res
}

func completeGlobals(prefix string, isZsh bool) []compResult {
	var res []compResult
	// Special handling for console/YAML key mode when prefix is exactly "console"/"YAML" or starts with "console."/"YAML."
	isConsoleKey := prefix == "console" || strings.HasPrefix(prefix, "console.")
	isYAMLKey := prefix == "YAML" || strings.HasPrefix(prefix, "YAML.")
	for _, g := range globalCompletions {
		if strings.HasPrefix(g, prefix) {
			if isZsh {
				if (isConsoleKey && strings.HasPrefix(g, "console.")) || (isYAMLKey && strings.HasPrefix(g, "YAML.")) {
					// key mode: display suffix after object, value full, typ key
					var display string
					if strings.HasPrefix(g, "console.") {
						display = strings.TrimPrefix(g, "console")
					} else {
						display = strings.TrimPrefix(g, "YAML")
					}
					res = append(res, compResult{display: display, value: g, typ: "key"})
				} else {
					res = append(res, compResult{display: g, value: g, typ: "global"})
				}
			} else {
				res = append(res, compResult{value: g})
			}
		}
	}
	return res
}

func completeFiles(prefix string, isZsh bool) []compResult {
	// Strip leading ./ if present
	origPrefix := prefix
	prefix = strings.TrimPrefix(prefix, "./")
	// Split at last /
	var dir, filePrefix string
	if idx := strings.LastIndex(prefix, "/"); idx != -1 {
		dir = prefix[:idx]
		if dir == "" {
			dir = "/"
		}
		filePrefix = prefix[idx+1:]
	} else {
		dir = "."
		filePrefix = prefix
	}
	// Handle absolute vs relative: dir as is (if prefix was absolute like /tmp/a, dir=/tmp, filePrefix=a)
	// If origPrefix started with ./, dir handling already stripped, value should not include ./? Our dir is without ./, value will be without ./, good.
	// List dir
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var res []compResult
	for _, e := range entries {
		name := e.Name()
		if name == "." || name == ".." {
			continue
		}
		if !strings.HasPrefix(name, filePrefix) {
			continue
		}
		isDir := e.IsDir()
		var display, value string
		if dir == "." {
			if isDir {
				display = name + "/"
				value = name
			} else {
				display = name
				value = name
			}
		} else {
			// dir is subdir or absolute
			// display is basename (+/ if dir)
			if isDir {
				display = name + "/"
			} else {
				display = name
			}
			// value is dir + "/" + name (for absolute, dir already absolute, e.g., /tmp + / + a.json = /tmp/a.json, good. For dir="/", need handle: "/" + "/" + name => "//name"? Actually if dir=="/", prefix was "/a" (dir="/", filePrefix="a"), value should be "/a.json", not "//a.json". Handle.
			if dir == "/" {
				value = "/" + name
			} else {
				// For dir like "subdir" (relative), value "subdir/c.json". Good.
				// For dir like "/tmp" (absolute), value "/tmp/a.json". Good.
				// For dir like "./"? Already stripped, dir should not be "./". Good.
				value = dir + "/" + name
			}
			// If origPrefix started with ./ and dir was stripped? Already handled (dir without ./, value without ./). Good.
			// What about origPrefix like "./subdir/c" (stripped to "subdir/c", dir="subdir", filePrefix="c", value="subdir/c.json", no ./). Matches observed (value without ./). Good.
		}
		_ = origPrefix
		if isZsh {
			res = append(res, compResult{display: display, value: value, typ: "file"})
		} else {
			res = append(res, compResult{value: value})
		}
	}
	sort.Slice(res, func(i, j int) bool {
		return res[i].value < res[j].value
	})
	return res
}

