	// If origPrefix started with ./, dir handling already stripped, value should not include ./? Our dir is without ./, value will be without ./, good.
	// List dir
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	var res []compResult
	for _, e := range entries {
		name := e.Name()
		if name == "." || name == ".." {
			continue
		}
		if !strings.HasPrefix(name, filePrefix) {
			continue
		}
		isDir := e.IsDir()
		var display, value string
		if dir == "." {
			if isDir {
				display = name + "/"
				value = name
			} else {
				display = name
				value = name
			}
		} else {
			// dir is subdir or absolute
			// display is basename (+/ if dir)
			if isDir {
				display = name + "/"
			} else {
				display = name
			}
			// value is dir + "/" + name (for absolute, dir already absolute, e.g., /tmp + / + a.json = /tmp/a.json, good. For dir="/", need handle: "/" + "/" + name => "//name"? Actually if dir=="/", prefix was "/a" (dir="/", filePrefix="a"), value should be "/a.json", not "//a.json". Handle.
