            os.Exit(1)
        }
        printValue(out, noInline, false)
        return
    }
    for _, v := range vals {
        out, evalErr := applyReducers(v, reducers, filename)
        if evalErr != nil {
            fmt.Fprintf(os.Stderr, "%s", evalErr.Error())
            os.Exit(1)
        }
        printValue(out, noInline, false)
    }
}

func applyReducers(input JSValue, reducers []string, filename string) (JSValue, error) {
    _ = filename
    cur := input
    for _, r := range reducers {
        var err error
        cur, err = evalReducer(cur, r)
        if err != nil {
            return nil, err
        }
        if _, ok := cur.(jsEmptyType); ok {
            break
        }
    }
    return cur, nil
}

func evalReducer(input JSValue, reducer string) (JSValue, error) {
    if reducer == "" {
        return input, nil
    }
    if reducer == "." {
        return input, nil
    }
    if reducer == "x" || reducer == "this" {
        return input, nil
    }
    return nil, fmt.Errorf("eval TODO for %s", reducer)
}

