func jsUnquote(s string, q byte) (string, error) {
    var b strings.Builder
    i := 1
    n := len(s)
    for i < n-1 {
        c := s[i]
        if c != 92 {
            b.WriteByte(c)
            i++
            continue
        }
        i++
        if i >= n-1 {
            break
        }
        e := s[i]
        i++
        switch e {
        case 110:
            b.WriteByte(10)
        case 116:
            b.WriteByte(9)
        case 114:
            b.WriteByte(13)
        case 98:
            b.WriteByte(8)
        case 102:
            b.WriteByte(12)
        case 118:
            b.WriteByte(11)
        case 48:
            b.WriteByte(0)
        case 39, 34, 92:
            b.WriteByte(e)
        case 120:
            if i+1 >= n-1 {
                return "", fmt.Errorf("bad escape")
            }
            hv := s[i : i+2]
            v, err := strconv.ParseUint(hv, 16, 32)
            if err != nil {
                return "", fmt.Errorf("bad escape")
            }
            b.WriteRune(rune(v))
            i += 2
        case 117:
            if i < n-1 && s[i] == 123 {
                j := i + 1
                for j < n-1 && s[j] != 125 {
                    j++
                }
                if j >= n-1 {
                    return "", fmt.Errorf("bad escape")
                }
                hv := s[i+1 : j]
                v, err := strconv.ParseUint(hv, 16, 32)
                if err != nil {
                    return "", fmt.Errorf("bad escape")
                }
                b.WriteRune(rune(v))
                i = j + 1
            } else {
                if i+3 >= n-1 {
                    return "", fmt.Errorf("bad escape")
                }
                hv := s[i : i+4]
                v, err := strconv.ParseUint(hv, 16, 32)
                if err != nil {
                    return "", fmt.Errorf("bad escape")
                }
                b.WriteRune(rune(v))
                i += 4
            }
        default:
            b.WriteByte(e)
        }
    }
    return b.String(), nil
}

