func jsTypeOf(v JSValue) string {
    switch v.(type) {
    case jsUndefinedType:
        return "undefined"
    case jsNullType:
        return "object"
    case JSBool:
        return "boolean"
    case JSNumber:
        return "number"
    case *JSBigInt:
        return "bigint"
    case JSString:
        return "string"
    case JSArray:
        return "object"
    case *JSObject:
        return "object"
    case *JSFunction, JSFunction:
        return "function"
    case JSDate, *JSDate:
        return "object"
    default:
        if _, ok := v.(jsEmptyType); ok {
            return "undefined"
        }
        return "object"
    }
}

func jsToBool(v JSValue) bool {
    switch x := v.(type) {
    case jsUndefinedType:
        return false
    case jsNullType:
        return false
    case JSBool:
        return bool(x)
    case JSNumber:
        f := float64(x)
        return f != 0 && !math.IsNaN(f)
    case *JSBigInt:
        return x.V.Sign() != 0
    case JSString:
        return len(string(x)) != 0
    default:
        return true
    }
}

func jsToNumber(v JSValue) (float64, *big.Int, bool, error) {
    switch x := v.(type) {
    case jsUndefinedType:
        return math.NaN(), nil, false, nil
    case jsNullType:
        return 0, nil, false, nil
    case JSBool:
        if bool(x) {
            return 1, nil, false, nil
        }
        return 0, nil, false, nil
    case JSNumber:
        return float64(x), nil, false, nil
    case *JSBigInt:
        return 0, x.V, true, nil
    case JSString:
        s := strings.TrimSpace(string(x))
        if s == "" {
            return 0, nil, false, nil
        }
        if s == "Infinity" || s == "+Infinity" {
            return math.Inf(1), nil, false, nil
        }
        if s == "-Infinity" {
            return math.Inf(-1), nil, false, nil
        }
        f, err := strconv.ParseFloat(s, 64)
        if err != nil {
            return math.NaN(), nil, false, nil
        }
        return f, nil, false, nil
    case JSArray:
        if len(x) == 0 {
            return 0, nil, false, nil
        }
        if len(x) == 1 {
            return jsToNumber(x[0])
        }
        s, _ := jsToString(JSValue(x))
        return jsToNumber(JSString(s))
    case *JSObject:
        s, _ := jsToString(JSValue(x))
        return jsToNumber(JSString(s))
    default:
        return math.NaN(), nil, false, nil
    }
}

func jsToString(v JSValue) (string, error) {
    switch x := v.(type) {
    case jsUndefinedType:
        return "undefined", nil
    case jsNullType:
        return "null", nil
    case JSBool:
        if bool(x) {
            return "true", nil
        }
        return "false", nil
    case JSNumber:
        return formatNumber(x), nil
    case *JSBigInt:
        return x.V.String(), nil
    case JSString:
        return string(x), nil
    case JSArray:
        var parts []string
        for _, e := range x {
            if isUndefined(e) || isNull(e) {
                parts = append(parts, "")
            } else {
                s, _ := jsToString(e)
                parts = append(parts, s)
            }
        }
        return strings.Join(parts, ","), nil
    case *JSObject:
        return "[object Object]", nil
    case *JSFunction, JSFunction:
        return "function", nil
    case JSDate:
        return x.Str, nil
    case *JSDate:
        return x.Str, nil
    default:
        return "", nil
    }
}

func jsToInt32(v JSValue) int32 {
    f, bi, isBig, _ := jsToNumber(v)
    if isBig {
        w := bi.Int64()
        return int32(w & 0xffffffff)
    }
    if math.IsNaN(f) || math.IsInf(f, 0) {
        return 0
    }
    m := math.Mod(f, 4294967296)
    if m < 0 {
        m += 4294967296
    }
    if m >= 2147483648 {
        return int32(m - 4294967296)
    }
    return int32(m)
