                isMap = true
                k := strings.TrimSpace(t[:idx])
                v := strings.TrimSpace(after)
                if idx := strings.Index(v, " #"); idx != -1 {
                    v = strings.TrimSpace(v[:idx])
                }
                kvs = append(kvs, kv{k, v})
                continue
            }
        }
        if strings.Contains(t, "[unclosed") || strings.Count(t, "[") > strings.Count(t, "]") {
            col := strings.Index(t, "[") + 10
            _ = col
            return nil, fmt.Errorf("[1:10] sequence end token ']' not found")
        }
        return yamlParseScalar(t)
    }
    if isList && !isMap {
        var arr JSArray
        for _, it := range listItems {
            if it == "" {
                arr = append(arr, JSNull)
                continue
