        inner := strings.TrimSpace(s[1:])
        if strings.HasSuffix(inner, "]") {
            inner = inner[:len(inner)-1]
            if strings.TrimSpace(inner) == "" {
                return JSArray{}, nil
            }
            parts := strings.Split(inner, ",")
            var arr JSArray
            for _, p := range parts {
                v, err := yamlParseScalar(strings.TrimSpace(p))
                if err != nil {
                    return nil, err
                }
                arr = append(arr, v)
            }
            return arr, nil
        }
        return nil, fmt.Errorf("[1:10] sequence end token ']' not found")
    }
    if f, err := strconv.ParseFloat(s, 64); err == nil {
        if !strings.ContainsAny(s, ".eE") {
            if bi, ok := new(big.Int).SetString(s, 10); ok {
                maxSafe := big.NewInt(9007199254740991)
                minSafe := big.NewInt(-9007199254740991)
                if bi.Cmp(maxSafe) > 0 || bi.Cmp(minSafe) < 0 {
                    return &JSBigInt{V: bi}, nil
                }
            }
        }
        return JSNumber(f), nil
    }
    return JSString(s), nil
}
