            }
            return nil, jsErrorFrame(reducer, "", msg)
        }
        return r, nil
    }
    return v, nil
}

func expandedOrEmpty(expanded, reducer string) string {
    if expanded != "" && expanded != reducer {
        return expanded
    }
    return ""
