        return JSBool(true), nil
    }
    if s == "false" {
        return JSBool(false), nil
    }
    if len(s) >= 2 && s[0] == 34 && s[len(s)-1] == 34 {
        uq, err := strconv.Unquote(s)
        if err != nil {
            return nil, err
        }
        return JSString(uq), nil
    }
    if len(s) >= 2 && s[0] == 39 && s[len(s)-1] == 39 {
        return JSString(s[1 : len(s)-1]), nil
    }
