    ttyFd int
    origTermios []byte
    out *os.File
}

func termSize(fd int) (w, h int, ok bool) {
    type winsize struct { r, c, x, y uint16 }
    var ws winsize
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
    if errno != 0 {
        return 0, 0, false
    }
    return int(ws.c), int(ws.r), true
}

func setRaw(fd int) ([]byte, error) {
    var termios [64]byte
    _, _, errno := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCGETS, uintptr(unsafe.Pointer(&termios[0])))
    if errno != 0 {
        return nil, errno
    }
    orig := append([]byte{}, termios[:]...)
    const (
        IXON = 0x400
        ICANON = 0x2
        ECHO = 0x8
        ISIG = 0x1
        IEXTEN = 0x8000
        OPOST = 0x1
    )
    lflag := *(*uint32)(unsafe.Pointer(&termios[12]))
    iflag := *(*uint32)(unsafe.Pointer(&termios[0]))
    oflag := *(*uint32)(unsafe.Pointer(&termios[4]))
    _ = iflag
    _ = oflag
    _ = IXON
    _ = OPOST
    _ = IEXTEN
    _ = ISIG
    lflag &^= (ICANON | ECHO)
    *(*uint32)(unsafe.Pointer(&termios[12])) = lflag
    cc := termios[16:]
    if len(cc) > 6 {
        cc[6] = 1
        cc[5] = 0
    }
    _, _, errno = syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&termios[0])))
    if errno != 0 {
        return nil, errno
    }
    return orig, nil
}

func restoreTerm(fd int, orig []byte) {
    if len(orig) < 64 || fd < 0 {
        return
    }
    var t [64]byte
    copy(t[:], orig)
    syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), syscall.TCSETS, uintptr(unsafe.Pointer(&t[0])))
}

func runTUI(path string, raw, yamlFlag, tomlFlag, strictFlag, noInline, slurp bool) {
    data, err := os.ReadFile(path)
    if err != nil {
        fmt.Fprintf(os.Stderr, "open %s: no such file or directory\n", path)
        os.Exit(1)
    }
    var vals []JSValue
    if raw {
        s := string(data)
        if len(data) == 0 {
            vals = nil
        } else {
            parts := strings.Split(s, "\n")
            if len(parts) > 0 && parts[len(parts)-1] == "" {
                parts = parts[:len(parts)-1]
            }
            for _, p := range parts {
                vals = append(vals, JSString(p))
            }
        }
    } else if yamlFlag {
        if len(data) != 0 {
            vals, err = yamlParseDocs(string(data))
            if err != nil {
                fmt.Fprintf(os.Stdout, "%s", yamlFormatError(string(data), err.Error()))
                os.Exit(1)
            }
        }
    } else if tomlFlag {
        v, err2 := tomlParse(string(data))
        if err2 != nil {
            panic(err2)
        }
        vals = []JSValue{v}
    } else {
        vals, err = parseJSONStream(data, strictFlag)
        if err != nil {
            fmt.Fprintf(os.Stderr, "%s", err.Error())
            os.Exit(1)
        }
    }
